  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

